"""Refuges + exit signage, generated by rule. Generic over any building
that declares/generates them -- no id/
coordinate beyond what the loaded Building actually has, except where a
test deliberately asserts on B1-L's own data to prove real geometry was
checked, not just the mechanism in the abstract."""

from __future__ import annotations

from pathlib import Path

import pytest

from dms.geometry.building import Building, Floor, Space
from dms.geometry.loader import load_site
from dms.geometry.primitives import Door, Rect, Refuge, Sign, Stair
from dms.geometry.refuge_check import validate_refuges
from dms.geometry.signage_check import validate_signs
from dms.geometry.signage_gen import apply_generated_signs
from dms.graph.builder import build_navigation_graph
from dms.scenario.agent_defaults import load_agent_defaults

CONFIG_PATH = Path(__file__).resolve().parents[1] / "configs" / "buildings" / "two_storey_large.yaml"


@pytest.fixture(scope="module")
def site():
    return load_site(CONFIG_PATH)


@pytest.fixture(scope="module")
def building(site):
    return site.get_building("B1")


@pytest.fixture(scope="module")
def agent_defaults():
    return load_agent_defaults()


def test_b1l_refuges_exist_and_pass_geometry_check(building, agent_defaults):
    """Refuges are generated automatically by `load_site` itself now (cheap
    geometry only, no field solve -- see dms/geometry/loader.py:
    _build_building) -- no explicit generation call needed here."""
    ff = building.get_floor("FF")
    assert len(ff.refuges) >= 1, "B1-L's realism pass should declare at least one FF refuge"
    problems = validate_refuges(building, min_lane_width_m=agent_defaults.min_lane_width_m)
    assert problems == []


def test_b1l_signs_exist_and_pass_signage_check(site, building, agent_defaults):
    apply_generated_signs(site, building, agent_defaults)
    assert any(f.signs for f in building.floors.values())
    nav = build_navigation_graph(site, building.id)
    problems = validate_signs(building, nav)
    assert problems == []


def test_refuge_overlapping_an_unrelated_stairs_footprint_is_rejected():
    """A refuge placed directly on top of a DIFFERENT stair's footprint
    (not the one it declares `serves_stair`) must be flagged -- the real
    bug this check exists to catch: a refuge only ever checked against its
    own declared stair can sit right next to a completely different one
    with nothing to catch it."""
    floor = Floor(id="L1", z=0.0, footprint=Rect(0.0, 0.0, 20.0, 20.0))
    floor.spaces["ST-A"] = Space(id="ST-A", floor="L1", name="ST-A", kind="stair", rect=Rect(0.0, 0.0, 4.0, 4.0))
    floor.spaces["ST-B"] = Space(id="ST-B", floor="L1", name="ST-B", kind="stair", rect=Rect(6.0, 0.0, 10.0, 4.0))
    floor.spaces["C-A"] = Space(id="C-A", floor="L1", name="C-A", kind="corridor", rect=Rect(4.0, 0.0, 6.0, 4.0))
    # Declares ST-A but actually overlaps ST-B's unrelated footprint.
    floor.refuges["R-bad"] = Refuge(id="R-bad", floor="L1", rect=Rect(6.5, 1.0, 8.0, 3.0), serves_stair="ST-A")
    building = Building(id="REFUGE-FIXTURE", origin=(0.0, 0.0), rotation_deg=0.0, wall_thickness_m=0.2)
    building.floors["L1"] = floor
    building.stairs["ST-A"] = Stair(
        id="ST-A", landings={"L1": "ST-A"}, width_m=1.2, enclosed=True, riser_m=0.17, tread_m=0.28, flights=2,
        floor_to_floor_m=4.0, footprints={"L1": Rect(0.0, 0.0, 4.0, 4.0)},
    )
    building.stairs["ST-B"] = Stair(
        id="ST-B", landings={"L1": "ST-B"}, width_m=1.2, enclosed=True, riser_m=0.17, tread_m=0.28, flights=2,
        floor_to_floor_m=4.0, footprints={"L1": Rect(6.0, 0.0, 10.0, 4.0)},
    )
    problems = validate_refuges(building, min_lane_width_m=1.0)
    assert any("overlaps stair ST-B's own footprint" in p for p in problems)


def test_refuge_overlapping_its_own_served_stairs_footprint_is_allowed():
    """The flip side: a refuge inside its OWN served stair's protected
    lobby is an explicitly valid placement (the rule's own wording), not a
    defect -- generate_refuges relies on this to place a refuge beside a
    door whose adjacent corridor is too narrow to hold one at all."""
    floor = Floor(id="L1", z=0.0, footprint=Rect(0.0, 0.0, 20.0, 20.0))
    floor.spaces["ST-A"] = Space(id="ST-A", floor="L1", name="ST-A", kind="stair", rect=Rect(0.0, 0.0, 10.0, 10.0))
    floor.refuges["R-ok"] = Refuge(id="R-ok", floor="L1", rect=Rect(1.0, 1.0, 3.0, 3.0), serves_stair="ST-A")
    building = Building(id="REFUGE-FIXTURE", origin=(0.0, 0.0), rotation_deg=0.0, wall_thickness_m=0.2)
    building.floors["L1"] = floor
    building.stairs["ST-A"] = Stair(
        id="ST-A", landings={"L1": "ST-A"}, width_m=1.2, enclosed=True, riser_m=0.17, tread_m=0.28, flights=2,
        floor_to_floor_m=4.0, footprints={"L1": Rect(0.0, 0.0, 10.0, 10.0)},
    )
    problems = validate_refuges(building, min_lane_width_m=1.0)
    assert problems == []


def test_refuge_overlapping_door_queue_zone_is_rejected():
    """A refuge placed right across a stair's own door must be flagged,
    even though it doesn't touch the stair's footprint itself."""
    floor = Floor(id="L1", z=0.0, footprint=Rect(0.0, 0.0, 20.0, 20.0))
    floor.spaces["ST-A"] = Space(id="ST-A", floor="L1", name="ST-A", kind="stair", rect=Rect(0.0, 0.0, 4.0, 4.0))
    floor.spaces["C-A"] = Space(id="C-A", floor="L1", name="C-A", kind="corridor", rect=Rect(4.0, 0.0, 10.0, 4.0))
    floor.doors["ST-A-d1"] = Door(id="ST-A-d1", floor="L1", axis="x", coord=4.0, lo=1.0, hi=2.5,
                                    kind="fire_door", space_a="ST-A", space_b="C-A")
    # Centred right in front of the door, well clear of the stair's own rect.
    floor.refuges["R-bad"] = Refuge(id="R-bad", floor="L1", rect=Rect(4.2, 1.0, 5.2, 2.5), serves_stair="ST-A")
    building = Building(id="REFUGE-FIXTURE", origin=(0.0, 0.0), rotation_deg=0.0, wall_thickness_m=0.2)
    building.floors["L1"] = floor
    building.stairs["ST-A"] = Stair(
        id="ST-A", landings={"L1": "ST-A"}, width_m=1.2, enclosed=True, riser_m=0.17, tread_m=0.28, flights=2,
        floor_to_floor_m=4.0, footprints={"L1": Rect(0.0, 0.0, 4.0, 4.0)},
    )
    problems = validate_refuges(building, min_lane_width_m=1.0)
    assert any("queue zone" in p for p in problems)


def test_sign_pointing_to_unavailable_exit_is_rejected():
    """`validate_signs` rejects an UNAVAILABLE-by-default target before ever
    touching the nav graph (checked first, same order the function itself
    uses) -- a real NavGraph is not needed to exercise this path, only a
    placeholder object the function never dereferences."""
    floor = Floor(id="L1", z=0.0, footprint=Rect(0.0, 0.0, 20.0, 10.0))
    floor.spaces["R1"] = Space(id="R1", floor="L1", name="R1", kind="room", rect=Rect(0.0, 0.0, 20.0, 10.0))
    floor.doors["X-1"] = Door(id="X-1", floor="L1", axis="y", coord=10.0, lo=4.0, hi=5.5,
                                kind="exit", default_state="UNAVAILABLE", space_a="R1", space_b="outside")
    floor.signs["S-1"] = Sign(id="S-1", floor="L1", x=5.0, y=5.0, points_to="X-1")
    building = Building(id="SIGN-FIXTURE", origin=(0.0, 0.0), rotation_deg=0.0, wall_thickness_m=0.2)
    building.floors["L1"] = floor
    problems = validate_signs(building, object())
    assert any("UNAVAILABLE" in p for p in problems)
